12	/**
13	 * AgentLoopContext represents the execution-scoped view of the world for a single
14	 * agent turn or sub-agent loop.
15	 */
16	export interface AgentLoopContext {
17	  /** The global runtime configuration. */
18	  readonly config: Config;
19	
20	  /** The unique ID for the current user turn or agent thought loop. */
21	  readonly promptId: string;
22	
23	  /** The registry of tools available to the agent in this context. */
24	  readonly toolRegistry: ToolRegistry;
25	
26	  /** The bus for user confirmations and messages in this context. */
27	  readonly messageBus: MessageBus;
28	
29	  /** The client used to communicate with the LLM in this context. */
30	  readonly geminiClient: GeminiClient;
31	}
