130	  constructor(options: CoreToolSchedulerOptions) {
131	    this.config = options.config;
132	    this.outputUpdateHandler = options.outputUpdateHandler;
133	    this.onAllToolCallsComplete = options.onAllToolCallsComplete;
134	    this.onToolCallsUpdate = options.onToolCallsUpdate;
135	    this.getPreferredEditor = options.getPreferredEditor;
136	    this.toolExecutor = new ToolExecutor(this.config);
137	    this.toolModifier = new ToolModificationHandler();
138	
139	    // Subscribe to message bus for ASK_USER policy decisions
140	    // Use a static WeakMap to ensure we only subscribe ONCE per MessageBus instance
141	    // This prevents memory leaks when multiple CoreToolScheduler instances are created
142	    // (e.g., on every React render, or for each non-interactive tool call)
143	    const messageBus = this.config.getMessageBus();
144	
145	    // Check if we've already subscribed a handler to this message bus
146	    if (!CoreToolScheduler.subscribedMessageBuses.has(messageBus)) {
147	      // Create a shared handler that will be used for this message bus
148	      const sharedHandler = (request: ToolConfirmationRequest) => {
149	        // When ASK_USER policy decision is made, respond with requiresUserConfirmation=true
150	        // to tell tools to use their legacy confirmation flow
151	        // eslint-disable-next-line @typescript-eslint/no-floating-promises
152	        messageBus.publish({
153	          type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
154	          correlationId: request.correlationId,
155	          confirmed: false,
156	          requiresUserConfirmation: true,
157	        });
158	      };
159	
160	      messageBus.subscribe(
161	        MessageBusType.TOOL_CONFIRMATION_REQUEST,
162	        sharedHandler,
163	      );
164	
165	      // Store the handler in the WeakMap so we don't subscribe again
166	      CoreToolScheduler.subscribedMessageBuses.set(messageBus, sharedHandler);
167	    }
168	  }
